def longest_word(words):
    words.sort()                                            # ensures immediate prefixes come first
    built = {''}
    result = ''
    for w in words:
        if w[:-1] in built:                                    # check just the IMMEDIATE prefix
            built.add(w)
            if len(w) > len(result):
                result = w
    return result

