import java.util.*;

public class Main {
    static String longestWord(String[] words) {
        Arrays.sort(words);                                        // ensures immediate prefixes come first
        Set<String> built = new HashSet<>();
        built.add("");
        String result = "";
        for (String w : words) {
            if (built.contains(w.substring(0, w.length() - 1))) {     // check just the IMMEDIATE prefix
                built.add(w);
                if (w.length() > result.length()) result = w;
            }
        }
        return result;
    }
}

