string longestWord(vector<string>& words) {
    sort(words.begin(), words.end());                              // ensures immediate prefixes come first
    unordered_set<string> built = {""};
    string result = "";
    for (auto& w : words) {
        if (built.count(w.substr(0, w.size() - 1))) {                  // check just the IMMEDIATE prefix
            built.insert(w);
            if (w.size() > result.size()) result = w;
        }
    }
    return result;
}
